/**
 * Tungaloy US (Inch) Edition Tool Catalog
 * 345 inch-specific tools extracted from:
 *   GC_2023-2024_US_Turning-Grooving.pdf (1036 pages)
 *   GC_2023-2024_US_Milling.pdf (1036 pages)
 *   GC_2023-2024_US_Drilling.pdf (204 pages)
 *
 * KEY FINDING: Turning inserts and milling inserts/endmills use IDENTICAL
 * ISO designations in both US and metric editions (same global products).
 * The US editions add ANSI designation cross-references and SFM/IPR cutting data.
 * Only the DRILLING section contains inch-specific SKUs (TIDU, TDXU, DSXU, DMXU, FDCU)
 * that differ from their metric counterparts (TID, TDX, DSX, DMX, FDC).
 *
 * Also includes 49 US cutting conditions (SFM/IPR) and
 * 622 ANSI-to-ISO insert designation mappings.
 *
 * All dimensions stored in mm (converted from inches: multiply by 25.4)
 * Generated by extract-tungaloy-us.py
 */

export interface TungaloyUSTool {
  designation: string;
  type: "exchangeable_head_drill" | "indexable_drill" | "solid_drill" | "flat_bottom_drill";
  cutting_diameter_mm: number;
  shank_diameter_mm: number;
  flute_length_mm?: number | null;
  overall_length_mm: number;
  ld_ratio: number;
}

export interface TungalayUSCuttingCondition {
  chipbreaker: string;
  grade: string;
  ap_min_in: number;
  ap_max_in: number;
  feed_min_ipr: number;
  feed_max_ipr: number;
  vc_min_sfm: number;
  vc_max_sfm: number;
}

export interface TungaloyANSItoISO {
  ansi_designation: string;
  iso_designation: string;
}

